"""Lexical toxicity / profanity heuristic with configurable threshold."""

from __future__ import annotations

from typing import Any

# Generated by GitHub Copilot - Nov-01-2026
from app.guardrails.models import GuardrailResult


class ToxicityFilterGuardrail:
    name = "toxicity_filter"

    _lexicon = frozenset(
        ["hate", "kill", "stupid", "idiot", "loser", "slur", "abuse", "violent", "threat", "harass"]
    )

    def _score(self, text: str) -> float:
        words = [w.strip(".,!?\"'").lower() for w in text.split()]
        if not words:
            return 0.0
        hits = sum(1 for w in words if w in self._lexicon)
        return min(1.0, hits / max(3, len(words) // 4))

    async def run(self, text: str, context: dict[str, Any] | None, **params: Any) -> GuardrailResult:
        threshold = float(params.get("threshold", 0.85))
        action = str(params.get("_action", params.get("action", "block")))
        score = self._score(text)
        if score >= threshold:
            if action == "block":
                return GuardrailResult(
                    text="",
                    blocked=True,
                    warnings=[f"Toxicity score {score:.2f} >= {threshold}"],
                )
            if action == "warn":
                return GuardrailResult(
                    text=text,
                    blocked=False,
                    warnings=[f"Toxicity score {score:.2f}"],
                )
            return GuardrailResult(
                text="[Content redacted due to toxicity policy]",
                blocked=False,
                warnings=[],
                redacted_fields=["toxicity"],
            )
        return GuardrailResult(text=text, blocked=False)
